import java.util.*;
import java.io.*;

public class PrimeFactors {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int a_input = Integer.parseInt(inputLine[0]);
        int b_input = Integer.parseInt(inputLine[1]);

        List<Integer> primes = generatePrimes(6000);
        Map<Integer, Integer> f_dict = new HashMap<>();
        f_dict.put(0, 0);
        f_dict.put(1, 1);
        f_dict.put(2, 2);

        for (int i = 3; i <= a_input; i++) {
            int val = 2 * f_dict.get(i - 1);
            for (int divisor : listAllFactors(i, primes)) {
                if (divisor >= 2 && divisor <= i) {
                    int quotient = i / divisor;
                    int prevDivisor = (i - 1) / divisor;
                    val += f_dict.get(quotient) - f_dict.get(prevDivisor);
                    val %= b_input;
                }
            }
            val %= b_input;
            f_dict.put(i, val);
        }
        System.out.println(f_dict.get(a_input));
    }

    private static List<Integer> generatePrimes(int limit) {
        List<Integer> primes = new ArrayList<>();
        for (int candidate = 2; candidate < limit; candidate++) {
            boolean isPrime = true;
            for (int prime : primes) {
                if (prime * prime > candidate) {
                    break;
                }
                if (candidate % prime == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(candidate);
            }
        }
        return primes;
    }

    private static Map<Integer, Integer> getPrimeFactorsMap(int n, List<Integer> primes) {
        Map<Integer, Integer> factorsMap = new HashMap<>();
        for (int prime : primes) {
            if (prime * prime > n) {
                break;
            }
            if (n % prime == 0) {
                int count = 0;
                while (n % prime == 0) {
                    n /= prime;
                    count++;
                }
                factorsMap.put(prime, count);
            }
        }
        if (n > 1) {
            factorsMap.put(n, 1);
        }
        return factorsMap;
    }

    private static List<Integer> listAllFactors(int n, List<Integer> primes) {
        Map<Integer, Integer> primeFactors = getPrimeFactorsMap(n, primes);
        List<Integer> factorsList = new ArrayList<>();
        factorsList.add(1);
        for (Map.Entry<Integer, Integer> entry : primeFactors.entrySet()) {
            int prime = entry.getKey();
            int powerCount = entry.getValue();
            List<Integer> tempList = new ArrayList<>();
            for (int val : factorsList) {
                for (int power = 0; power <= powerCount; power++) {
                    tempList.add(val * (int) Math.pow(prime, power));
                }
            }
            factorsList = tempList;
        }
        return factorsList;
    }
}
